#include <bits/stdc++.h>
using namespace std;

struct State {
    int u, v, sum;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<State> states;
    states.reserve(2 * M);

    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        int s = a + b;
        states.push_back({a, b, s});
        states.push_back({b, a, s});
    }

    sort(states.begin(), states.end(), [](const State& x, const State& y) {
        return x.sum > y.sum;
    });

    vector<int> best(N + 1, 0);
    vector<pair<int, int>> updates;
    updates.reserve(states.size());

    for (size_t i = 0; i < states.size(); ) {
        int currentSum = states[i].sum;
        size_t j = i;
        updates.clear();

        while (j < states.size() && states[j].sum == currentSum) {
            int u = states[j].u;
            int v = states[j].v;
            int val = (best[v] == 0 ? 2 : best[v] + 1);
            updates.emplace_back(u, val);
            ++j;
        }

        for (auto [u, val] : updates) {
            if (val > best[u]) best[u] = val;
        }

        i = j;
    }

    for (int i = 1; i <= N; ++i) {
        if (i > 1) cout << ' ';
        cout << max(1, best[i]);
    }
    cout << '\n';

    return 0;
}
